String rootFromAmznTrace(def raw) {
  if (raw == null) {
    return null;
  }
  String s = raw.toString();
  int idx = s.toLowerCase().indexOf('root=');
  if (idx < 0) {
    return null;
  }
  int start = idx + 5;
  int end = s.indexOf(';', start);
  String id = (end < 0 ? s.substring(start) : s.substring(start, end)).trim();
  if (id.isEmpty() || id.equals('-')) {
    return null;
  }
  return id;
}
def headers = ctx.aws?.waf?.request?.headers;
def raw = null;
if (headers instanceof Map) {
  raw = headers.get('X-Amzn-Trace-Id');
  if (raw == null) {
    raw = headers.get('x-amzn-trace-id');
  }
  if (raw == null) {
    for (entry in headers.entrySet()) {
      def k = entry.getKey();
      if (k != null && k.toString().equalsIgnoreCase('X-Amzn-Trace-Id')) {
        raw = entry.getValue();
        break;
      }
    }
  }
}
def id = rootFromAmznTrace(raw);
if (id != null) {
  if (ctx.trace == null) {
    ctx.trace = new HashMap();
  }
  ctx.trace.id = id;
}

String headerIgnoreCase(def headers, def names) {
  if (!(headers instanceof Map)) {
    return null;
  }
  for (name in names) {
    def v = headers.get(name);
    if (v != null) {
      String s = v.toString().trim();
      if (!s.isEmpty()) {
        return s;
      }
    }
  }
  for (entry in headers.entrySet()) {
    def k = entry.getKey();
    if (k == null) {
      continue;
    }
    String lk = k.toString().toLowerCase();
    for (name in names) {
      if (lk.equals(((String) name).toLowerCase())) {
        def v = entry.getValue();
        if (v != null) {
          String s = v.toString().trim();
          if (!s.isEmpty()) {
            return s;
          }
        }
      }
    }
  }
  return null;
}
def headers = ctx.aws?.waf?.request?.headers;
def tnt = headerIgnoreCase(headers, ['tnt', 'Tnt', 'TNT', 'tenant', 'Tenant', 'tenantid']);
if (tnt != null) {
  ctx.tnt = tnt;
}
